e\\" style=\\"background-image: url(\'assets/images/portfolio/boudoir.jpg\');\\"></div>\\r\\n    <div class=\\"portfolio-overlay\\"></div>\\r\\n  </div>\\r\\n\\r\\n  <!-- ================= CENTER INDEX NAVIGATION (EXACT JADE HA PORTFOLIO) ================= -->\\r\\n  <div class=\\"relative z-10 my-auto text-center px-4 w-full max-w-[1240px] mx-auto\\">\\r\\n\\r\\n    <!-- Subtitle (Exact from Jade Ha Portfolio: Calluna 15px normal) -->\\r\\n    <p class=\\"collection-desc mb-6 sm:mb-8 text-white/90\\">\\r\\n      st. louis luxury photo studio\\r\\n    </p>\\r\\n\\r\\n    <!-- The 6 Large Category Links: Exact Jade Ha (2 Columns: Left Right-Aligned, Right Left-Aligned) -->\\r\\n    <nav id=\\"portfolio-nav\\" class=\\"grid grid-cols-2 gap-x-12 sm:gap-x-16 md:gap-x-20 gap-y-2 sm:gap-y-3 md:gap-y-4 max-w-[860px] mx-auto items-center\\">\\r\\n      <div class=\\"text-right\\">\\r\\n        <a href=\\"/fashion/\\" class=\\"portfolio-giant-link\\" data-bg=\\"bg-fashion\\">\\r\\n          FASHION\\r\\n        </a>\\r\\n      </div>\\r\\n      <div class=\\"text-left\\">\\r\\n        <a href=\\"/couples/\\" class=\\"portfolio-giant-link\\" data-bg=\\"bg-couples\\">\\r\\n          COUPLES\\r\\n        </a>\\r\\n      </div>\\r\\n\\r\\n      <div class=\\"text-right\\">\\r\\n        <a href=\\"/portraits/\\" class=\\"portfolio-giant-link\\" data-bg=\\"bg-portraits\\">\\r\\n          PORTRAITS\\r\\n        </a>\\r\\n      </div>\\r\\n      <div class=\\"text-left\\">\\r\\n        <a href=\\"/branding/\\" class=\\"portfolio-giant-link\\" data-bg=\\"bg-branding\\">\\r\\n          BRANDING\\r\\n        </a>\\r\\n      </div>\\r\\n\\r\\n      <div class=\\"text-right\\">\\r\\n        <a href=\\"/maternity/\\" class=\\"portfolio-giant-link\\" data-bg=\\"bg-maternity\\">\\r\\n          MATERNITY\\r\\n        </a>\\r\\n      </div>\\r\\n      <div class=\\"text-left\\">\\r\\n        <a href=\\"/boudoir/\\" class=\\"portfolio-giant-link\\" data-bg=\\"bg-boudoir\\">\\r\\n          BOUDOIR\\r\\n        </a>\\r\\n      </div>\\r\\n    </nav>\\r\\n\\r\\n  </div>\\r\\n\\r\\n  <!-- Bottom Location Indicator -->\\r\\n  <div class=\\"relative z-10 pb-6 text-center text-xs tracking-widest text-white/40 uppercase\\">\\r\\n    Jade Ha Studio - Photography\\r\\n  </div>\\r\\n\\r\\n  <!-- ================= ROBUST HOVER IN / HOVER OUT SCRIPT ================= -->\\r\\n  <script>\\r\\n    const links = document.querySelectorAll(\'.portfolio-giant-link\');\\r\\n    const bgs = document.querySelectorAll(\'.bg-crossfade\');\\r\\n\\r\\n    function deactivateAll() {\\r\\n      bgs.forEach(bg => bg.classList.remove(\'active\'));\\r\\n    }\\r\\n\\r\\n    function activateBg(targetId) {\\r\\n      bgs.forEach(bg => {\\r\\n        if (bg.id === targetId) {\\r\\n          bg.classList.add(\'active\');\\r\\n        } else {\\r\\n          bg.classList.remove(\'active\');\\r\\n        }\\r\\n      });\\r\\n    }\\r\\n\\r\\n    links.forEach(link => {\\r\\n      // Hover IN: show this category\'s background image\\r\\n      link.addEventListener(\'mouseenter\', () => {\\r\\n        const targetId = link.getAttribute(\'data-bg\');\\r\\n        activateBg(targetId);\\r\\n      });\\r\\n\\r\\n      // Hover OUT: revert to pure #2b2421\\r\\n      link.addEventListener(\'mouseleave\', (e) => {\\r\\n        // If moving directly into another giant link, let its mouseenter handle it\\r\\n        if (!e.relatedTarget || typeof e.relatedTarget.closest !== \'function\' || !e.relatedTarget.closest(\'.portfolio-giant-link\')) {\\r\\n          deactivateAll();\\r\\n        }\\r\\n      });\\r\\n    });\\r\\n\\r\\n    // Global cursor safety: anywhere not over an ambroise link reverts to #2b2421\\r\\n    document.addEventListener(\'mousemove\', (e) => {\\r\\n      if (!e.target || typeof e.target.closest !== \'function\' || !e.target.closest(\'.portfolio-giant-link\')) {\\r\\n        deactivateAll();\\r\\n      }\\r\\n    });\\r\\n\\r\\n    // Window leaves or tab switch: revert to #2b2421\\r\\n    document.addEventListener(\'mouseleave\', deactivateAll);\\r\\n    window.addEventListener(\'blur\', deactivateAll);\\r\\n  </script>\\r\\n  <script src=\\"header-nav.js\\"></script>"
    },
    {
        "slug": "meet-the-team",
        "title": "Meet The Team",
        "isFront": false,
        "template": "default",
        "html": "<main class=\\"pt-28 sm:pt-36 pb-20 max-w-[1108px] mx-auto px-6\\">\\r\\n    \\r\\n    <div class=\\"space-y-16 md:space-y-20 mb-20 md:mb-28\\">\\r\\n      \\r\\n      <!-- 1. JADE -->\\r\\n      <article class=\\"grid grid-cols-1 md:grid-cols-10 gap-8 md:gap-12 items-center\\">\\r\\n        <div class=\\"md:col-span-4 aspect-[5/6] overflow-hidden bg-zinc-100 shadow-sm\\">\\r\\n          <img src=\\"##THEME_ASSETS##/images/meet-the-team/jade-ha-405.jpg\\" alt=\\"Jade Ha - Photographer &amp; Retoucher\\" class=\\"w-full h-full object-cover object-center\\" loading=\\"lazy\\">\\r\\n        </div>\\r\\n        <div class=\\"md:col-span-6 flex flex-col justify-center\\">\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] tracking-[0.45px] uppercase text-[#333333] mb-3\\">Jade Ha - Photographer &amp; Retoucher</h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[2.3] tracking-[0.45px] text-[#000000]\\">\\r\\n            Hi, I’m Jade! I’ve been photographing women for more than a decade, and I still love that every shoot gives us the chance to create something completely different. I’m incredibly hands-on, obsessed with the details, and I’ll guide you through every pose and expression so you never have to wonder what to do in front of the camera. I want your day to feel creative, collaborative, and entirely too much fun. I can’t wait to work with you!\\r\\n          </p>\\r\\n        </div>\\r\\n      </article>\\r\\n\\r\\n      <!-- 2. KAREN -->\\r\\n      <article class=\\"grid grid-cols-1 md:grid-cols-10 gap-8 md:gap-12 items-center\\">\\r\\n        <div class=\\"md:col-span-4 aspect-[5/6] overflow-hidden bg-zinc-100 shadow-sm\\">\\r\\n          <img src=\\"##THEME_ASSETS##/images/meet-the-team/webjade_4473-edit.jpg\\" alt=\\"Karen - Booking Concierge\\" class=\\"w-full h-full object-cover object-center\\" loading=\\"lazy\\">\\r\\n        </div>\\r\\n        <div class=\\"md:col-span-6 flex flex-col justify-center\\">\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] tracking-[0.45px] uppercase text-[#333333] mb-3\\">Karen - Booking Concierge</h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[2.3] tracking-[0.45px] text-[#000000]\\">\\r\\n            Hi! I’m Karen and I’m here to walk you through the process of planning your luxe portrait experience. I will keep you on point to make sure every detail is covered, so your day of pampering can be just that. Looking forward to working with you and seeing your gorgeous photos soon!\\r\\n          </p>\\r\\n        </div>\\r\\n      </article>\\r\\n\\r\\n      <!-- 3. LAUREN -->\\r\\n      <article class=\\"grid grid-cols-1 md:grid-cols-10 gap-8 md:gap-12 items-center\\">\\r\\n        <div class=\\"md:col-span-4 aspect-[5/6] overflow-hidden bg-zinc-100 shadow-sm\\">\\r\\n          <img src=\\"##THEME_ASSETS##/images/meet-the-team/lauren-shoot-assistant.png\\" alt=\\"Lauren - Shoot Assistant\\" class=\\"w-full h-full object-cover object-center\\" loading=\\"lazy\\">\\r\\n        </div>\\r\\n        <div class=\\"md:col-span-6 flex flex-col justify-center\\">\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] tracking-[0.45px] uppercase text-[#333333] mb-3\\">Lauren - Shoot Assistant</h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[2.3] tracking-[0.45px] text-[#000000]\\">\\r\\n            Hey friends! I\'m Lauren, and I can\'t wait to assist you during your shoot. I\'ll be there to make the day fun, comfortable, and provide help to you and Jade any way I can to elevate your entire experience. (I’m also a videographer, so don\'t mind me while I capture some beautiful behind the scenes footage for you!) I\'m so excited for the opportunity to work with you while Jade creates beautiful moments that will last a lifetime!\\r\\n          </p>\\r\\n        </div>\\r\\n      </article>\\r\\n\\r\\n    </div>\\r\\n\\r\\n  </main>"
    },
    {
        "slug": "luxury-photoshoot",
        "title": "A Client\'s Experience",
        "isFront": false,
        "template": "default",
        "html": "<main class=\\"pt-28 sm:pt-36 pb-20 px-4 sm:px-6 max-w-[1108px] mx-auto\\">\\r\\n    \\r\\n    <!-- Page Title: Ambroise Std 57px (fluid clamp) 300 centered matching Jade Ha -->\\r\\n    <h1 class=\\"text-center font-ambroise text-[34px] sm:text-[44px] md:text-[57px] font-light leading-[1.3] md:leading-[79.8px] tracking-[2.28px] text-[#222222] uppercase mb-6 md:mb-8\\">\\r\\n      PORTRAITURE, REIMAGINED\\r\\n    </h1>\\r\\n\\r\\n    <!-- Hero Image & Caption (Full 10-Column Content Width) -->\\r\\n    <div class=\\"mb-14 text-center\\">\\r\\n      <img src=\\"##THEME_ASSETS##/images/luxury-photoshoot/luxuryfamilyportraitsstlouis.jpg\\" alt=\\"Luxury Portraiture Experience\\" class=\\"w-full object-cover\\">\\r\\n      <p class=\\"font-calluna italic text-[12px] leading-[20.16px] tracking-[0.45px] text-[#222222] mt-3 text-center\\">\\r\\n        Celebrity style sessions are the new normal.\\r\\n      </p>\\r\\n    </div>\\r\\n\\r\\n    <!-- Self-Care Reimagined Section -->\\r\\n    <div class=\\"mb-14\\">\\r\\n      <h3 class=\\"font-calluna font-bold text-[15px] leading-[15px] tracking-[0.45px] text-[#222222] uppercase mb-4\\">\\r\\n        SELF-CARE, REIMAGINED\\r\\n      </h3>\\r\\n      <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222] font-normal mb-8\\">\\r\\n        There’s something pretty incredible about having an entire day that’s just about you. Champagne, professional hair and makeup, beautiful clothes, and a creative team focused on making you look and feel amazing. It’s part photoshoot, part escape, and a little bit of an indulgence. And honestly, that’s exactly what it’s supposed to be. Maybe that’s why so many of my clients come back and do it all over again.\\r\\n      </p>\\r\\n      <hr class=\\"border-t border-zinc-200\\">\\r\\n    </div>\\r\\n\\r\\n    <!-- Why Is This Different Section -->\\r\\n    <div class=\\"mb-14 space-y-4\\">\\r\\n      <h3 class=\\"font-calluna font-bold text-[15px] leading-[15px] tracking-[0.45px] text-[#222222] uppercase mb-4\\">\\r\\n        WHY IS THIS DIFFERENT FROM OTHER PORTRAIT SESSIONS?\\r\\n      </h3>\\r\\n      <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n        This isn’t a show up, take a few pretty pictures, and head home kind of shoot. We plan everything together, from what you’ll wear to the hair, makeup, lighting, and overall direction of each look. And once you’re in front of my camera, I’ll guide you through every bit of it.\\r\\n      </p>\\r\\n      <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n        Most of my clients aren’t models. They’re women who want beautiful photographs of themselves, whether they’re celebrating something, stepping into a new chapter, or simply deciding it’s finally time to do this for themselves. My style is fashion-inspired, polished, and editorial, but the images should still feel unmistakably like you. If that sounds like what you’ve been looking for, you can read what past clients have shared about their experience <a href=\\"/testimonials/\\" class=\\"underline hover:text-[#ff9061] transition-colors\\">here</a>.\\r\\n      </p>\\r\\n    </div>\\r\\n\\r\\n    <!-- Section 1: Included & Emily Travis BTS Image (2-Column Magazine Layout: 7 cols text, 5 cols photo) -->\\r\\n    <div class=\\"grid grid-cols-1 md:grid-cols-12 gap-8 md:gap-10 items-start mb-16\\">\\r\\n      <div class=\\"md:col-span-7 space-y-6\\">\\r\\n        <div>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222] mb-3\\">\\r\\n            <strong class=\\"font-bold uppercase tracking-[0.45px]\\">WHAT IS INCLUDED IN MY PORTRAIT SESSION?</strong><br>\\r\\n            Everything you need to feel prepared, look incredible, and actually enjoy the experience:<br>\\r\\n            - a planning consultation with me<br>\\r\\n            - a custom styling mood board<br>\\r\\n            - a 4-hour photoshoot with 3–4 looks<br>\\r\\n            - champagne in the studio<br>\\r\\n            - professional hair + makeup with touchups throughout your shoot<br>\\r\\n            - access to my studio wardrobe<br>\\r\\n            - complete posing and expression guidance from me<br>\\r\\n            - my signature retouching on every image you purchase<br>\\r\\n            - a private Reveal to see your images and choose your favorites\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            <strong class=\\"font-bold uppercase tracking-[0.45px]\\">WHAT SHOULD I WEAR?</strong><br>\\r\\n            We’ll figure that out together! Before your shoot, we’ll talk through the overall look and feel you want, and I’ll help you choose pieces that photograph beautifully and still feel like you. Once you’re booked, I’ll create a custom mood board with ideas for your specific shoot, including silhouettes, textures, colors, and places to shop. You’ll also have access to my studio wardrobe of gowns, bodysuits, and accessories.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            <strong class=\\"font-bold uppercase tracking-[0.45px]\\">HOW DOES THE PRICING WORK?</strong><br>\\r\\n            Your session fee is due when you book and reserves your date and creative team. Your portraits are purchased separately at your Reveal, after you’ve seen your images and know exactly what you love. For full pricing and collection details, simply fill out the <a href=\\"/contact/\\" class=\\"underline hover:text-[#ff9061] transition-colors\\">contact form</a> and we’ll send everything over.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            <strong class=\\"font-bold uppercase tracking-[0.45px]\\">WHAT IS YOUR AVAILABILITY LIKE?</strong><br>\\r\\n            I only take a limited number of shoots each month so I can be very hands-on with every client, from planning through the final edits. My calendar does tend to fill in advance, so if you have a particular date or timeframe in mind, I recommend reaching out early.\\r\\n          </p>\\r\\n        </div>\\r\\n      </div>\\r\\n\\r\\n      <div class=\\"md:col-span-5\\">\\r\\n        <img src=\\"##THEME_ASSETS##/images/luxury-photoshoot/7U1A9496.jpg\\" alt=\\"behind the scenes with Emily Travis of Champagne &amp; Chanel\\" class=\\"w-full object-cover\\">\\r\\n        <p class=\\"font-calluna italic text-[12px] leading-[20.16px] tracking-[0.45px] text-[#222222] mt-2 text-center\\">\\r\\n          behind the scenes with Emily Travis of Champagne &amp; Chanel\\r\\n        </p>\\r\\n      </div>\\r\\n    </div>\\r\\n\\r\\n    <!-- Section 2: Client Text Message (Left 5 cols) + Nervous / Retouching / Digitals (Right 7 cols) -->\\r\\n    <div class=\\"grid grid-cols-1 md:grid-cols-12 gap-8 md:gap-10 items-start mb-16\\">\\r\\n      <div class=\\"md:col-span-5\\">\\r\\n        <img src=\\"##THEME_ASSETS##/images/luxury-photoshoot/client-text-jade-ha.jpg\\" alt=\\"Client Review Text Message\\" class=\\"w-full object-cover border border-zinc-200\\">\\r\\n        <p class=\\"font-calluna italic text-[12px] leading-[20.16px] tracking-[0.45px] text-[#222222] mt-2 text-center\\">\\r\\n          The best kind of text to get! This will never get old. xx\\r\\n        </p>\\r\\n      </div>\\r\\n\\r\\n      <div class=\\"md:col-span-7 space-y-6\\">\\r\\n        <div>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222] mb-3\\">\\r\\n            <strong class=\\"font-bold uppercase tracking-[0.45px]\\">I’M NERVOUS. IS THIS REALLY FOR SOMEONE LIKE ME?</strong><br>\\r\\n            Yes. And I promise, almost everyone is nervous at first.<br>\\r\\n            The women you see throughout my portfolio are real clients, not professional models. You do not need to know how to pose, what to do with your hands, or how to make the right expression. That’s my job. I’ll guide you through all of it throughout the shoot so you never have to wonder what you’re supposed to be doing. Just show up. We’ll take care of the rest.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222] mb-3\\">\\r\\n            <strong class=\\"font-bold uppercase tracking-[0.45px]\\">WILL YOU PHOTOSHOP OR RETOUCH MY IMAGES?</strong><br>\\r\\n            Yes. Every portrait you purchase receives my signature retouching and the same polished, editorial finish you see throughout my portfolio. I want you to look like the very best version of yourself, while still looking like <em>you</em>.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            <strong class=\\"font-bold uppercase tracking-[0.45px]\\">WHAT IF I ONLY WANT DIGITALS?</strong><br>\\r\\n            Digitals and printed portraits are the same price. You’re investing in the creation of the image itself, rather than the format you choose to receive it in. Every portrait you purchase includes the corresponding digital file.\\r\\n          </p>\\r\\n        </div>\\r\\n      </div>\\r\\n    </div>\\r\\n\\r\\n    <!-- Section 3: Large Studio Photo Reclining on Chair -->\\r\\n    <div class=\\"mb-14\\">\\r\\n      <img src=\\"##THEME_ASSETS##/images/luxury-photoshoot/stlouisportraitphotographer.jpg\\" alt=\\"St. Louis Luxury Portrait Photographer Studio\\" class=\\"w-full object-cover\\">\\r\\n    </div>\\r\\n\\r\\n    <!-- Section 4: Design Looks & Studio Products -->\\r\\n    <div class=\\"mb-16 space-y-6\\">\\r\\n      <div>\\r\\n        <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n          <strong class=\\"font-bold uppercase tracking-[0.45px]\\">HOW DO YOU DESIGN THE LOOKS?</strong><br>\\r\\n          It all starts with the wardrobe. Once we decide what you’re wearing, I build everything else around it, including the hair, makeup, backdrop, and lighting. Every detail works together to create the final image. If you have inspiration you love, send it my way! I love seeing what you’re drawn to, and we can use that as a starting point while still making the shoot feel completely your own.\\r\\n        </p>\\r\\n      </div>\\r\\n\\r\\n      <div>\\r\\n        <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n          <strong class=\\"font-bold uppercase tracking-[0.45px]\\">WHAT KIND OF PRODUCTS DOES THE STUDIO OFFER?</strong><br>\\r\\n          At your Reveal, you’ll see approximately 150 of the best images from your shoot and choose the portraits you love most. From there, your selections receive my signature retouching and can be enjoyed digitally or as finished artwork. The studio offers coffee-table albums, framed wall art, and beautiful print options including matted prints, canvas, and metal. We’ll help you choose what makes the most sense for your images, your home, and how you actually want to enjoy them.\\r\\n        </p>\\r\\n      </div>\\r\\n\\r\\n      <div class=\\"pt-6\\">\\r\\n        <hr class=\\"border-t border-zinc-200\\">\\r\\n      </div>\\r\\n    </div>\\r\\n\\r\\n    <!-- Section 5: Exact FAQ\'S matching Jade Ha (42px Ambroise Std) -->\\r\\n    <div class=\\"mb-20\\">\\r\\n      <h2 class=\\"font-ambroise text-[32px] sm:text-[36px] md:text-[42px] font-light leading-[1.4] md:leading-[58.8px] tracking-[1.68px] text-[#222222] uppercase mb-8\\">\\r\\n        FAQ’S\\r\\n      </h2>\\r\\n      \\r\\n      <div class=\\"space-y-6\\">\\r\\n        <div>\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] leading-[15px] tracking-[0.45px] text-[#222222] uppercase mb-2\\">\\r\\n            WILL I REALLY LOOK AS POLISHED AS THE WOMEN ON YOUR SITE?\\r\\n          </h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            Yes! Every woman you see on my site is a real client. The lighting, styling, posing, hair and makeup, and retouching all play a part in creating the finished images you see. You don’t need to arrive knowing how to pose or somehow magically be photogenic. That’s what I’m here for.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] leading-[15px] tracking-[0.45px] text-[#222222] uppercase mb-2\\">\\r\\n            WHAT IF I ONLY WANT DIGITALS?\\r\\n          </h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            Digitals and printed portraits are the same price. You’re investing in the creation of the image itself, rather than the format you choose to receive it in. Every portrait you purchase includes the corresponding digital file.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] leading-[15px] tracking-[0.45px] text-[#222222] uppercase mb-2\\">\\r\\n            DO YOU PHOTOGRAPH EXTENDED FAMILIES?\\r\\n          </h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            I don’t offer extended family sessions. My work is focused on individuals and couples and is much more fashion-inspired and editorial than traditional family photography.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] leading-[15px] tracking-[0.45px] text-[#222222] uppercase mb-2\\">\\r\\n            DO YOU TRAVEL?\\r\\n          </h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            I photograph all of my sessions in my St. Louis studio, but many of my clients travel in to work with me. The studio is about 30 minutes from the airport.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] tracking-[0.45px] text-[#222222] uppercase mb-2\\">\\r\\n            WHAT SHOULD I WEAR?\\r\\n          </h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            We’ll figure that out together! Once you’re booked, I’ll create a custom mood board for your shoot with styling ideas, outfit inspiration, and suggestions for where to shop. You’ll also have access to my studio wardrobe.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] tracking-[0.45px] text-[#222222] uppercase mb-2\\">\\r\\n            HOW MUCH RETOUCHING IS INCLUDED?\\r\\n          </h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            Every portrait you purchase includes my signature retouching and the same polished, editorial finish you see throughout my portfolio. The goal is always for you to look incredible, but still completely like yourself.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] tracking-[0.45px] text-[#222222] uppercase mb-2\\">\\r\\n            HOW MANY LOOKS WILL I HAVE DURING MY SESSION?\\r\\n          </h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            We typically photograph 3–4 different looks, and they absolutely don’t have to feel the same. You might want something glamorous, something sexy, something simple and timeless, or something a little unexpected. We’ll plan each look together so you get plenty of variety while the final collection still feels like <em>you</em>.\\r\\n          </p>\\r\\n        </div>\\r\\n\\r\\n        <div>\\r\\n          <h3 class=\\"font-calluna font-bold text-[15px] tracking-[0.45px] text-[#222222] uppercase mb-2\\">\\r\\n            I’M NERVOUS. IS THIS REALLY FOR SOMEONE LIKE ME?\\r\\n          </h3>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222] mb-3\\">\\r\\n            Absolutely. Most of my clients are nervous when they walk in.\\r\\n          </p>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222] mb-3\\">\\r\\n            You don’t need to know how to pose. You don’t need to practice expressions in the mirror. And you definitely don’t need to walk in feeling wildly confident in front of a camera. I’ll guide you through every pose and expression from beginning to end.\\r\\n          </p>\\r\\n          <p class=\\"font-calluna text-[15px] leading-[34.5px] tracking-[0.45px] text-[#222222]\\">\\r\\n            All you have to do is show up. I’ve got the rest.\\r\\n          </p>\\r\\n        </div>\\r\\n      </div>\\r\\n    </div>\\r\\n\\r\\n  </main>"
    },
